def es_balanceado(cadena: str) -> bool:
    stack = []
    pares = {')': '(', ']': '[', '}': '{'}
    for c in cadena:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack.pop() != pares[c]:
                return False
    return len(stack) == 0

