from random import randint
from time import sleep


class Personaje(ABC):

    def __init__(self, nombre, x, y, energia):
        self.nombre = nombre
        self.x = x
        self.y = y
        self.energia = energia

    def simular(self):
        while self.energia > 0:
            sleep(1)
            self.saludar()
            self.moverse()
            self.gastar_energia()
        print("Perdí toda mi energía :(")

    @abstractmethod
    def moverse(self):
        pass

    @abstractmethod
    def gastar_energia(self):
        pass

    @abstractmethod
    def saludar(self):
        print(f"Soy {self.nombre}. Estoy en {(self.x, self.y)}.")

class Enemigo(Personaje):

    def moverse(self):
        # Se mueven aleatoriamente por el mapa
        self.x += randint(-1, 1)
        self.y += randint(-1, 1)

    def gastar_energia(self):
        # Gastan energía a tasa constante
        self.energia -= 1
        self.energia = max(0, self.energia)

    def saludar(self):
        # Agrega un grito por sobre la implementación original
        print("¡Te atraparé!")
        super().saludar()

import math
from abc import ABC, abstractmethod

class Figura(ABC):

    @abstractmethod
    def __init__(self):
        pass

    @abstractmethod
    def area(self):
        pass

    @abstractmethod
    def perimetro(self):
        pass

class Cuadrado(Figura):
    def __init__(self, lado: float) -> None:
        super().__init__()
        self._lado = lado

class Cuadrado(Figura):
    def __init__(self, lado: float) -> None:
        super().__init__()
        self.lado = lado

    def area(self):
        return math.pow(self.lado, 2)

    def perimetro(self):
        return 4 * self.lado

class Circulo(Figura):
    def __init__(self, radio: float) -> None:
        super().__init__()
        self.radio = radio

    def area(self):
        return math.pi * math.pow(self.radio, 2)

    def perimetro(self):
        return 2 * math.pi * self.radio

