import functools

def en_mayusculas(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        resultado = func(*args, **kwargs)
        return str(resultado).upper()
    return wrapper

@en_mayusculas
def saludar(nombre: str) -> str:
    return f'hola, {nombre}'

