from abc import ABC, abstractmethod

class CombustibleMixin:
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.combustible = 50.0

    def cargar_combustible(self, litros: float):
        self.combustible += litros

class Vehiculo(ABC):
    def __init__(self, velocidad: float = 0.0, **kwargs):
        super().__init__(**kwargs)
        self.velocidad = velocidad

    @abstractmethod
    def acelerar(self, delta: float):
        pass

class Auto(CombustibleMixin, Vehiculo):
    def acelerar(self, delta: float):
        self.velocidad += delta
        self.combustible -= delta * 0.1

