import threading
from collections import deque

class BufferConcurrente:
    def __init__(self, capacidad: int = 10):
        self.capacidad = capacidad
        self.buffer = deque()
        self.lock = threading.Lock()

    def poner(self, item):
        with self.lock:
            if len(self.buffer) < self.capacidad:
                self.buffer.append(item)
                return True
            return False

    def sacar(self):
        with self.lock:
            if self.buffer:
                return self.buffer.popleft()
            return None

