class ProtocoloRed:
    @staticmethod
    def crear_mensaje(comando: str, datos: str) -> bytes:
        cmd_b = comando.encode('ascii')[:1]
        payload_b = datos.encode('utf-8')
        largo_b = len(payload_b).to_bytes(4, 'big')
        return cmd_b + largo_b + payload_b

    @staticmethod
    def leer_mensaje(paquete: bytes) -> tuple[str, str]:
        cmd = paquete[:1].decode('ascii')
        largo = int.from_bytes(paquete[1:5], 'big')
        datos = paquete[5:5+largo].decode('utf-8')
        return (cmd, datos)

