from collections import deque

def bfs_camino_corto(grafo: dict, inicio, fin) -> list:
    cola = deque([[inicio]])
    visitados = {inicio}
    while cola:
        camino = cola.popleft()
        nodo = camino[-1]
        if nodo == fin:
            return camino
        for vecino in grafo.get(nodo, []):
            if vecino not in visitados:
                visitados.add(vecino)
                cola.append(camino + [vecino])
    return []

