def tiene_ciclo(grafo: dict) -> bool:
    visitados = set()
    def dfs(nodo, padre):
        visitados.add(nodo)
        for vecino in grafo.get(nodo, []):
            if vecino not in visitados:
                if dfs(vecino, nodo):
                    return True
            elif vecino != padre:
                return True
        return False
    for n in grafo:
        if n not in visitados:
            if dfs(n, None):
                return True
    return False

from collections import deque

def grado_separacion(grafo: dict, u1: str, u2: str) -> int:
    if u1 == u2:
        return 0
    cola = deque([(u1, 0)])
    visitados = {u1}
    while cola:
        actual, dist = cola.popleft()
        if actual == u2:
            return dist
        for vecino in grafo.get(actual, []):
            if vecino not in visitados:
                visitados.add(vecino)
                cola.append((vecino, dist + 1))
    return -1

